// Group long-form videos by channel, score each against that channel's median
const byChannel = {};
for (const { json: v } of $input.all()) (byChannel[v.channelName] ??= []).push(v);

const outliers = [];
for (const [channel, videos] of Object.entries(byChannel)) {
  const views = videos.map(v => v.viewCount).sort((a, b) => a - b);
  const mid = Math.floor(views.length / 2);
  const median = views.length % 2 ? views[mid] : (views[mid - 1] + views[mid]) / 2;
  for (const v of videos) {
    const ratio = v.viewCount / median;
    if (ratio >= 3) outliers.push({ json: { channel, title: v.videoTitle, url: v.videoUrl, views: v.viewCount, channel_median: median, ratio: +ratio.toFixed(1), other_titles: videos.filter(o => o !== v).map(o => o.videoTitle).slice(0, 8) } });
  }
}
return outliers.sort((a, b) => b.json.ratio - a.json.ratio);

